import local.tvmorph.tv.VideoSizing;import java.util.Arrays;
public class VideoSizingCheck{public static void main(String[] args){if(!Arrays.equals(VideoSizing.measure("fit",1920,1080,1440,1080),new int[]{1440,1080}))throw new AssertionError("fit");if(!Arrays.equals(VideoSizing.measure("fill",1920,1080,1440,1080),new int[]{1920,1440}))throw new AssertionError("fill");if(!Arrays.equals(VideoSizing.measure("stretch",1920,1080,1440,1080),new int[]{1920,1080}))throw new AssertionError("stretch");System.out.println("PASS: fit preserves aspect, fill crops, stretch matches screen dimensions.");}}
